import fs from'node:fs';import vm from'node:vm';import{createRodAbsorptionEngine}from'./rod-absorption-native.mjs';import{CLS14}from'../../src/builder/06-data-2014-classes.js';import{SP14}from'../../src/builder/07-data-2014-spells.js';
const read=p=>fs.readFileSync(new URL('../../src/'+p,import.meta.url),'utf8'),data=vm.createContext({DataEnv:{slot:{}},FEATS:{},LU_X:[],ACTS:{},SAVE_NOTES:[]});vm.runInContext(read('data/wotc11-magic-items-2014.js'),data);vm.runInContext(read('data/wotc07-feats-2014.js'),data);
export const originalTceRows=structuredClone(data.DataEnv.slot.WXI.tce),originalInitiate2014={feat:structuredClone(data.FEATS['Magic Initiate (2014)']),rules:structuredClone(data.DataEnv.slot.DM_SP),wx:structuredClone(data.DataEnv.slot.WX)};
const prepared={Bard:['Charm Person','Vicious Mockery'],Sorcerer:['Burning Hands','Fire Bolt'],Warlock:['Hold Person','Eldritch Blast'],Wizard:['Burning Hands','Fire Bolt'],Cleric:['Cure Wounds','Sacred Flame'],Paladin:['Cure Wounds','Sacred Flame']};
export function createTceSpellBonusEngine({item="+2 Rhythm-Maker's Drum",inventory,main='Bard',secondary='Sorcerer',spells=prepared[main]||[],secondarySpells=prepared[secondary]||[],level=5,secondaryLevel=5,actorRuleset='2024',background,picks,customization={},mutate=()=>{}}={}){
 const e=createRodAbsorptionEngine({main,secondary,spells,secondarySpells,level,secondaryLevel,background,picks,inventory:inventory??[{n:item,q:1,eq:true,attuned:true}]}),c=e.c;
 c.WXI.tce=structuredClone(originalTceRows);c.genv.WXI=c.WXI;c.DMGI=c.DMGI.concat(originalTceRows.filter(row=>!c.DMGI.some(value=>value[0]===row[0])));for(const row of originalTceRows)c.DMAP[row[0]]=structuredClone(row);c.DM14S=null;c.B.src={core:true,phb:true,phb14:true,dmg:true,dmg14:true,tce:true};c.B.base.INT=18;c.B.base.WIS=18;c.B.base.CHA=18;c.B.rs=actorRuleset;c.S.cust=structuredClone(customization);vm.runInContext(read('data/spfull-spell-text.js'),c);
 if(actorRuleset==='2014'){vm.runInContext(read('builder/18-ui-spells.js').split('\n').find(line=>line.startsWith('function xl14(')),c);c.SP14=structuredClone(SP14);for(const part of [main,secondary].filter(Boolean))if(CLS14[part])Object.assign(c.CLASSES[part],structuredClone(CLS14[part].base));const overlay=read('builder/09c-logic-edition-overlays.js'),start=overlay.indexOf('let SP14S=null;'),end=overlay.indexOf('/* Standalone actor-native');vm.runInContext(overlay.slice(start,end).replace(/export /g,''),c);c.sp14Set(true,true);}
 mutate(c);e.setC(e.project());return e;
}
export function addOriginalInitiate2014(engine,selectedClass,spell){const c=engine.c;c.FEATS['Magic Initiate (2014)']=structuredClone(originalInitiate2014.feat);c.genv.DM_SP=structuredClone(originalInitiate2014.rules);c.DM_SP=c.genv.DM_SP;c.genv.WX=structuredClone(originalInitiate2014.wx);c.B.ch.feat4={feat:'Magic Initiate (2014)'};c.B.ch['cp-feat4']=[selectedClass];c.B.ch['pks1-feat4']=[spell];engine.setC(engine.project());return engine;}

export function projectLegacyTce(engine){const c=engine.c,snapshot=JSON.parse(fs.readFileSync(new URL('./tce-spell-bonus-pre-u59-consumer.json',import.meta.url),'utf8'));if(createHash('sha256').update(snapshot.source).digest('hex')!==snapshot.sha256)throw Error('Pre-U59 native reducer changed');const previous={bonus:c.spItemB,sources:c.spItemSrc};try{vm.runInContext(snapshot.source.replace(/export /g,''),c);return engine.project()}finally{c.spItemB=previous.bonus;c.spItemSrc=previous.sources}}
