export function deriveTceAttackValues(engine,C){const scores=engine.c.abilScores().sc,n={C,S:{},D:{mod:Object.fromEntries(Object.entries(scores).map(([k,v])=>[k,Math.floor((v-10)/2)])),score:scores,atk:[]},B:{},defenderAttackDelta,ABN:{STR:'Strength',DEX:'Dexterity',CON:'Constitution',INT:'Intelligence',WIS:'Wisdom',CHA:'Charisma'},num:(v,d=0)=>Number.isFinite(+v)?+v:d,part:(s,v)=>({s,v}),appendDefenderAttackPart:()=>{},mwB:()=>0,ammoBonus:()=>null,cuK:()=>null};vm.createContext(n);const app=read('app/06-logic-derivation.js'),start=app.indexOf('function deriveFn1Step1('),end=app.indexOf('function deriveFn1Step2(',start);vm.runInContext(app.slice(start,end),n);return C.attacks.map((row,index)=>n.deriveFn1Step1(row,engine.c.pbOf(engine.c.TL()),{},0,()=>{},index).hit)}
